import {paperToyWHistory} from './paper-toy-w-history.mjs';

// Paper-aligned teaching page. The browser reads one cached fit and its W
// checkpoints; it never starts another optimizer run.
export function createPaperLab(){
  const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
  const payload=paperToyWHistory??{};
  const data=payload;
  const model=payload.model??{};
  const genes=(data.genes??['G1','G2','G3','G4','G5','G6']).slice(0,6);
  const fallbackW=Array.from({length:genes.length},()=>Array(genes.length).fill(0));
  const prior=(data.prior?.skeleton??fallbackW).map(row=>row.slice(0,genes.length));
  const f=(v,n=3)=>Number(v??0).toFixed(n);
  const copyW=w=>w.map(row=>row.slice(0,genes.length));
  const snapshots=(payload.snapshots??model.wSnapshots??[]).map(s=>({epoch:Number(s.epoch??0),W:copyW(s.W??fallbackW)})).filter(s=>s.W.length===genes.length);
  // The final panel follows the same recorded trajectory as the slider.  The
  // fitted best-checkpoint W remains in payload.model.rates for audit, while
  // the page itself replays the terminal cached optimization state.
  const finalW=copyW(snapshots.at(-1)?.W??model.rates?.W??fallbackW);
  if(!snapshots.length)snapshots.push({epoch:Number(model.epochs??0),W:copyW(finalW)});
  const history=payload.history??model.history??[];
  const edges=[];
  for(let target=0;target<genes.length;target++)for(let source=0;source<genes.length;source++)if(target!==source&&Number(prior[target]?.[source]??0)>0)edges.push({target,source,prior:1});
  const candidates=[];
  for(let target=0;target<genes.length;target++)for(let source=0;source<genes.length;source++)if(target!==source&&Number(prior[target]?.[source]??0)<=0)candidates.push({target,source,prior:0,candidate:true});
  let step=0,mode='hard',selected=0,timer=null,playing=false;
  const progress=()=>step/100;
  const snapshotIndex=()=>Math.min(snapshots.length-1,Math.max(0,Math.round(progress()*(snapshots.length-1))));
  const currentMatrix=()=>snapshots[snapshotIndex()]?.W??finalW;
  const currentWeight=e=>Number(currentMatrix()[e.target]?.[e.source]??0);
  const finalWeight=e=>Number(finalW[e.target]?.[e.source]??0);
  const regularizedWeight=e=>finalWeight(e)*(.78-.12*Math.min(1,Math.abs(finalWeight(e))/1.1));
  const shownFinalWeight=e=>mode==='soft_regularized'&&e.prior?regularizedWeight(e):finalWeight(e);
  const signedClass=w=>w>0?'positive':'negative';
  const status=(e,cur,fin)=>{if(e.candidate)return Math.abs(cur)>.08?'先验外候选 · 已出现':'先验外候选 · 当前为 0';const a=Math.abs(fin),raw=Math.abs(finalWeight(e));if(mode==='soft_regularized'&&a<raw*.95)return '先验边 · 正则显示';if(a>=.5)return '先验边 · 强化';if(a>=.15)return '先验边 · 保留';return '先验边 · 弱化';};
  const $=id=>document.getElementById(id);
  const nodePos=[{x:48,y:44},{x:138,y:44},{x:228,y:44},{x:48,y:184},{x:138,y:184},{x:228,y:184}];
  const svgShell=(kind,title)=>`<div class="paper-net-card"><div class="paper-net-title"><b>${title}</b><span>${kind==='prior'?'结构 mask':kind==='current'?'第 '+snapshots[snapshotIndex()].epoch+' 轮缓存 W':'最终缓存 W'}</span></div><svg id="paper-net-${kind}" viewBox="0 0 276 230" role="img" aria-label="${title}"></svg></div>`;
  function networkSvg(kind){
    const svg=$("paper-net-"+kind);if(!svg)return;
    const titleSpan=svg.parentElement?.querySelector('.paper-net-title span');
    if(titleSpan)titleSpan.textContent=kind==='prior'?'结构 mask':kind==='current'?`第 ${snapshots[snapshotIndex()].epoch} 轮缓存 W`:'最终缓存 W';
    const defs='<defs><marker id="paper-arrow-'+kind+'" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="context-stroke"/></marker></defs>';
    const drawEdges=mode==='soft'&&kind==='current'?[...edges,...candidates]:edges;
    const lines=drawEdges.map((e,i)=>{const a=nodePos[e.source],b=nodePos[e.target],dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ox=dx/len*18,oy=dy/len*18,x1=a.x+ox,y1=a.y+oy,x2=b.x-ox,y2=b.y-oy,value=kind==='prior'?e.prior:(kind==='final'?shownFinalWeight(e):currentWeight(e)),w=kind==='prior'?1.8:Math.max(.8,Math.min(7,Math.abs(value)*4.2)),color=kind==='prior'?'#b59a6a':e.candidate?'#bd873d':value>=0?'#168c8e':'#8d6ab6',opacity=kind==='current'?(Math.abs(value)<.001?.18:.95):1,active=i===selected?1:0,dash=kind==='prior'?'5 4':e.candidate?'2 4':'';return `<line data-paper-edge="${i}" x1="${f(x1,1)}" y1="${f(y1,1)}" x2="${f(x2,1)}" y2="${f(y2,1)}" stroke="${color}" stroke-width="${f(w,2)}" stroke-linecap="round" opacity="${opacity}" ${dash?`stroke-dasharray="${dash}"`:''} marker-end="url(#paper-arrow-${kind})"/><circle cx="${f((x1+x2)/2,1)}" cy="${f((y1+y2)/2,1)}" r="${active?5:0}" fill="#c68431"/>`;}).join('');
    const nodes=nodePos.slice(0,genes.length).map((p,i)=>`<g><circle cx="${p.x}" cy="${p.y}" r="17" fill="${i===selected?'#f0dfbc':'#edf4f7'}" stroke="${i===selected?'#bd7b2d':'#6d8997'}" stroke-width="2"/><text x="${p.x}" y="${p.y+5}" text-anchor="middle" font-size="14" font-weight="600" fill="#38586a">${esc(genes[i])}</text></g>`).join('');
    svg.innerHTML=defs+lines+nodes;svg.querySelectorAll('[data-paper-edge]').forEach(el=>el.addEventListener('click',()=>{selected=+el.dataset.paperEdge;refresh();}));
  }
  function edgeTable(){
    const tableEdges=mode==='soft'?[...edges,...candidates]:edges;
    const rows=tableEdges.map((e,i)=>{const cur=currentWeight(e),fin=shownFinalWeight(e),delta=Math.abs(fin)-Math.abs(cur),cls=status(e,cur,fin);return `<tr class="${i===selected?'selected':''}" data-paper-row="${i}"><td><b>${genes[e.source]} → ${genes[e.target]}</b></td><td>${e.prior?'支持':'无'}</td><td class="${signedClass(cur)}">${f(cur)}</td><td class="${signedClass(fin)}">${f(fin)}</td><td>${f(delta)}</td><td><span class="paper-state ${cls.includes('强化')?'strong':cls.includes('正则')?'weak':cls.includes('出现')?'new':''}">${cls}</span></td></tr>`;}).join('');
    return `<div class="table-scroll"><table class="paper-edges"><thead><tr><th>边</th><th>先验</th><th>缓存当前 W</th><th>最终 W</th><th>剩余变化</th><th>解释</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  function heatmap(){return `<div class="paper-heatmap" role="img" aria-label="最终调控矩阵热图"><div></div>${genes.map(g=>`<b>${esc(g)}</b>`).join('')}${genes.map((g,i)=>`<b>${esc(g)}</b>${genes.map((_,j)=>{const v=shownFinalWeight({target:i,source:j,prior:prior[i]?.[j]});const a=Math.min(1,Math.abs(v)/1.1),bg=i===j?'#f4f6f7':v>=0?`rgba(22,140,142,${.16+.68*a})`:`rgba(141,106,182,${.16+.68*a})`;return `<span style="background:${bg}" title="${genes[j]} → ${genes[i]}: ${f(v)}">${i===j?'—':f(v,2)}</span>`;}).join('')}`).join('')}</div>`;}
  function historySvg(){const svg=$('paper-loss-chart');if(!svg||!history.length)return;const W=720,H=190,pad={l:42,r:18,t:18,b:30},vals=history.map(x=>x.validation_loss??x.train_loss),lo=Math.min(...vals),hi=Math.max(...vals),X=i=>pad.l+(W-pad.l-pad.r)*i/Math.max(1,vals.length-1),Y=v=>pad.t+(H-pad.t-pad.b)*(v-lo)/Math.max(1,hi-lo),path=vals.map((v,i)=>`${i?'L':'M'} ${f(X(i),1)} ${f(Y(v),1)}`).join(' ');svg.innerHTML=`<line x1="${pad.l}" y1="${H-pad.b}" x2="${W-pad.r}" y2="${H-pad.b}" stroke="#d9e4e8"/><line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${H-pad.b}" stroke="#d9e4e8"/><path d="${path}" fill="none" stroke="#168c8e" stroke-width="2.5"/><text x="${pad.l}" y="${H-8}" font-size="10" fill="#8094a0">epoch 1</text><text x="${W-pad.r}" y="${H-8}" text-anchor="end" font-size="10" fill="#8094a0">epoch ${history.at(-1).epoch}</text><text x="${pad.l-8}" y="${pad.t+4}" text-anchor="end" font-size="10" fill="#8094a0">${f(hi,1)}</text><text x="${pad.l-8}" y="${H-pad.b+4}" text-anchor="end" font-size="10" fill="#8094a0">${f(lo,1)}</text>`;}
  function summary(){const active=edges.filter(e=>Math.abs(finalWeight(e))>=.08),visible=(mode==='soft'?[...edges,...candidates]:edges).filter(e=>Math.abs(currentWeight(e))>=.08),positive=active.filter(e=>finalWeight(e)>0).length,negative=active.filter(e=>finalWeight(e)<0).length;return `<div class="paper-summary"><div><span>六基因</span><b>${genes.length}</b></div><div><span>先验支持边</span><b>${edges.length}</b></div><div><span>当前可见边</span><b>${visible.length}</b></div><div><span>最终正 / 负</span><b>${positive} / ${negative}</b></div></div>`;}
  function template(){return `<section class="paper-page"><section class="paper-hero"><div><span class="eyebrow">REGVELO · 论文实验</span><h1>先验网络怎样进入动力学，最后又改变成什么？</h1><p>按照论文 Figure 1A 的训练逻辑，把六基因先验 GRN（基因调控网络）、潜时间、转录率和 ODE 放到同一条可回传的计算链中。拖动训练进度，查看一次固定拟合中每 10 轮保存的 W 快照。</p></div><div class="paper-hero-badge"><b>六基因缓存回放</b><span>Encoder · Decoder · W/b · β/γ · ODE</span></div></section><section class="paper-panel paper-flow"><div class="paper-panel-head"><div><span class="paper-kicker">01 / PAPER EXPERIMENT</span><h2>论文中的完整训练路径</h2><p>先验边提供结构路由；页面读取训练时保存的 W，不重新启动优化器。</p></div></div><div class="paper-flow-grid"><div><b>Ms / Mu</b><small>spliced + unspliced</small></div><i>→</i><div><b>Encoder</b><small>q(z|x), z</small></div><i>→</i><div><b>时间 Decoder</b><small>t<sub>ng</sub></small></div><i>→</i><div><b>GRN + ODE</b><small>α(t), β, γ → u/s</small></div><i>→</i><div><b>ELBO</b><small>loss → backward</small></div></div><div class="paper-flow-loop"><span>prior GRN / mask</span><b>↘</b><span>Transcription predictor W,b</span><b>↘</b><span>动态表达和概率观测</span><b>↘</b><span>AdamW 更新</span></div></section><section class="paper-panel paper-controls"><div class="paper-control-row"><label>训练策略<select id="paper-mode"><option value="hard">hard：只显示先验允许边</option><option value="soft">soft：同时显示先验外边</option><option value="soft_regularized">soft_regularized：正则化显示</option></select></label><label class="paper-range">缓存进度 <output id="paper-step-out"></output><input id="paper-step" type="range" min="0" max="100" value="0"></label><button id="paper-play" class="primary">播放训练路径</button><button id="paper-reset">回到初始化</button></div><p id="paper-status" class="paper-status"></p></section><section class="paper-panel"><div class="paper-panel-head"><div><span class="paper-kicker">02 / EDGE DYNAMICS</span><h2>先验骨架、训练中间态、最终网络</h2><p>箭头方向为 regulator → target；颜色表示 W 的正负，线宽表示缓存权重绝对值。</p></div><div id="paper-summary">${summary()}</div></div><div class="paper-networks">${svgShell('prior','先验 GRN')}${svgShell('current','缓存训练中间态')}${svgShell('final','最终推断网络')}</div><div class="paper-legend"><span><i class="prior"></i>先验结构</span><span><i class="positive"></i>正调控</span><span><i class="negative"></i>负调控</span><span><i class="candidate"></i>先验外边</span><span>每 10 轮读取一个固定 W 快照</span></div></section><section class="paper-panel"><div class="paper-panel-head"><div><span class="paper-kicker">03 / EDGE-BY-EDGE</span><h2>模型网络与先验网络具体差在哪里？</h2><p>先验是二值结构；缓存 W 是带方向和强度的调控权重。</p></div></div><div id="paper-edge-table">${edgeTable()}</div></section><section class="paper-panel paper-bottom-grid"><div><span class="paper-kicker">04 / MATRIX VIEW</span><h2>最终 W 矩阵</h2><p>行是 target，列是 regulator；对角线为自调控位置。</p>${heatmap()}</div><div><span class="paper-kicker">05 / TRAINING CURVE</span><h2>论文实验的验证损失</h2><svg id="paper-loss-chart" viewBox="0 0 720 190" role="img" aria-label="验证损失曲线"></svg><p class="paper-note">W 使用一次固定拟合过程中的每 10 轮快照；页面回放这些缓存值，不把重新插值当作训练 checkpoint。</p></div></section><section class="paper-panel paper-boundary"><h2>这个页面与论文实验的关系</h2><p>当前页面使用六基因 Hill toy 数据和同一份先验 skeleton；它保留论文页面的计算顺序与可视化形式，用于说明先验结构如何限制 W。它不把 toy 权重解释成真实生物网络。</p><p>当前页面的 hard / soft / soft_regularized 只控制图中显示哪些缓存边以及是否做显示投影；不会重新训练模型。</p></section></section>`;}
  function refresh(){const s=snapshots[snapshotIndex()]??snapshots.at(-1);$('paper-step').value=step;$('paper-step-out').textContent=`${step}% · 第 ${s.epoch} 轮 · ${snapshotIndex()+1}/${snapshots.length}`;$('paper-mode').value=mode;$('paper-status').textContent=mode==='hard'?`hard：只显示 ${edges.length} 条先验支持边，当前读取第 ${s.epoch} 轮缓存 W。`:mode==='soft'?`soft：显示 ${edges.length} 条支持边和 ${candidates.length} 条先验外边；本次硬约束拟合中先验外 W 保持为 0。`:`soft_regularized：对缓存最终 W 做显示投影；底层快照仍保持原值。`;['prior','current','final'].forEach(networkSvg);$('paper-summary').innerHTML=summary();$('paper-edge-table').innerHTML=edgeTable();$('paper-edge-table').querySelectorAll('[data-paper-row]').forEach(el=>el.addEventListener('click',()=>{selected=+el.dataset.paperRow;refresh();}));historySvg();}
  function stop(){if(timer!==null)clearTimeout(timer);timer=null;playing=false;if($('paper-play'))$('paper-play').textContent='播放训练路径';}
  function play(){stop();playing=true;$('paper-play').textContent='暂停';const tick=()=>{if(!playing)return;if(step>=100){stop();return;}step=Math.min(100,step+Math.max(1,100/Math.max(1,snapshots.length-1)));refresh();timer=setTimeout(tick,180);};tick();}
  function setup(){$('paper-step').oninput=()=>{step=+$('paper-step').value;refresh();};$('paper-mode').onchange=()=>{mode=$('paper-mode').value;refresh();};$('paper-reset').onclick=()=>{stop();step=0;selected=0;refresh();};$('paper-play').onclick=()=>playing?stop():play();refresh();}
  return {template,setup,stop,refresh,state:()=>({step,mode,selected,playing,genes,prior,finalW,current:currentMatrix(),snapshots:snapshots.length})};
}
